class ManifestSpec:
    """ManifestSpec defines the desired state of Manifest."""

    def __init__(
        self,
        group: str,
        version: str,
        title: str,
        supported_core_versions: list[str],
        description: str | None = None,
        supported_endpoints: list[str] | None = None,
        requirements: list[Requirement] | None = None,
        author: str | None = None,
        app_info: AppInfo | None = None,
        components: list[ManifestComponent] | None = None,
        dependencies: list[ManifestDependency] | None = None,
        image: str | None = None,
        git_reference: str | None = None,
        git_path_prefix: str | None = None,
    ):
        """Initializes the instance.

        Args:
            group: The Group components and their respective Kinds reside in
            version: The Version components and their respective Kinds reside in
            title: Friendly name to use when displaying this Manifest, e.g. Interface
            supported_core_versions: Supported core versions, i.e. the versions of the EDA core that this Manifest is compatible with
            description: Summary description of the application described by this Manifest
            supported_endpoints: Endpoints supported by the application described by this Manifest
            requirements: Other applications this application depends on/interacts with
            author: Author of the application described by this Manifest
            app_info: Additional information relating the application described by this Manifest
            components: A list of components provided in this Manifest
            dependencies: A list of other artifacts, images, or files this Manifest depends on
            image: OCI image to use as a source for artifacts provided in this Manifest
            git_reference: Reference to a git hash or tag within the EDA application repository at which to load resources from components in this Manifest
            git_path_prefix: A path prefix to apply when resolving any relative paths within this Manifest in the EDA application repository
        """
        self.group = group
        self.version = version
        self.title = title
        self.description = description
        self.supported_endpoints = supported_endpoints
        self.supported_core_versions = supported_core_versions
        self.requirements = requirements
        self.author = author
        self.app_info = app_info
        self.components = components
        self.dependencies = dependencies
        self.image = image
        self.git_reference = git_reference
        self.git_path_prefix = git_path_prefix

    def to_input(self):
        _rval = {}
        _rval[constants.Y_GROUP] = self.group
        _rval[constants.Y_VERSION] = self.version
        _rval[constants.Y_TITLE] = self.title
        if self.description is not None:
            _rval[constants.Y_DESCRIPTION] = self.description
        if self.supported_endpoints is not None:
            _rval[constants.Y_SUPPORTEDENDPOINTS] = self.supported_endpoints
        _rval[constants.Y_SUPPORTEDCOREVERSIONS] = self.supported_core_versions
        if self.requirements is not None:
            _rval[constants.Y_REQUIREMENTS] = [x.to_input() for x in self.requirements]
        if self.author is not None:
            _rval[constants.Y_AUTHOR] = self.author
        if self.app_info is not None:
            _rval[constants.Y_APPINFO] = self.app_info.to_input()
        if self.components is not None:
            _rval[constants.Y_COMPONENTS] = [x.to_input() for x in self.components]
        if self.dependencies is not None:
            _rval[constants.Y_DEPENDENCIES] = [x.to_input() for x in self.dependencies]
        if self.image is not None:
            _rval[constants.Y_IMAGE] = self.image
        if self.git_reference is not None:
            _rval[constants.Y_GITREFERENCE] = self.git_reference
        if self.git_path_prefix is not None:
            _rval[constants.Y_GITPATHPREFIX] = self.git_path_prefix
        return _rval

    @staticmethod
    def from_input(obj) -> "ManifestSpec | None":
        if not obj:
            return None
        _group = obj.get(constants.Y_GROUP)
        _version = obj.get(constants.Y_VERSION)
        _title = obj.get(constants.Y_TITLE)
        _description = obj.get(constants.Y_DESCRIPTION)
        _supported_endpoints = obj.get(constants.Y_SUPPORTEDENDPOINTS)
        _supported_core_versions = obj.get(constants.Y_SUPPORTEDCOREVERSIONS)
        _requirements = []
        if obj.get(constants.Y_REQUIREMENTS) is not None:
            for _e in obj.get(constants.Y_REQUIREMENTS):
                _requirements.append(Requirement.from_input(_e))
        _author = obj.get(constants.Y_AUTHOR)
        _app_info = AppInfo.from_input(obj.get(constants.Y_APPINFO))
        _components = []
        if obj.get(constants.Y_COMPONENTS) is not None:
            for _e in obj.get(constants.Y_COMPONENTS):
                _components.append(ManifestComponent.from_input(_e))
        _dependencies = []
        if obj.get(constants.Y_DEPENDENCIES) is not None:
            for _e in obj.get(constants.Y_DEPENDENCIES):
                _dependencies.append(ManifestDependency.from_input(_e))
        _image = obj.get(constants.Y_IMAGE)
        _git_reference = obj.get(constants.Y_GITREFERENCE)
        _git_path_prefix = obj.get(constants.Y_GITPATHPREFIX)
        return ManifestSpec(
            group=_group,
            version=_version,
            title=_title,
            description=_description,
            supported_endpoints=_supported_endpoints,
            supported_core_versions=_supported_core_versions,
            requirements=_requirements,
            author=_author,
            app_info=_app_info,
            components=_components,
            dependencies=_dependencies,
            image=_image,
            git_reference=_git_reference,
            git_path_prefix=_git_path_prefix,
        )


